def verify():
    data=ROOT/'docs/literature/omics-2023-2026';p=json.loads((data/'biomart-catalog-validation.json').read_bytes());assert p['schema_version']==1 and p['status']=='passed-seven-existing-biomaRt-roles-and-one-scoped-integration' and (p['new_scoped_integrations'],p['including_existing_adapters'],p['missing_integrations'],p['unrelated_tool_rows_preserved'])==(82,85,249,389) and not p['whole_goal_complete'] and not p['whole_paper_reproduced'] and not p['website_deployed'];assert pin(data/'biomart-catalog-support.zip')==p['archive'];files=unpack(data/'biomart-catalog-support.zip',p)
    for name,value in p['source_pins'].items():assert pin(ROOT/name)==value and byte_pin(files['current-source/'+name])==value
    for name,value in p['parent_proofs'].items():assert pin(ROOT/name)==value
    parent=json.loads((data/'loftee-catalog-validation.json').read_bytes());assert pin(data/'loftee-catalog-support.zip')==parent['archive'];old=unpack(data/'loftee-catalog-support.zip',parent)
    for name,value in parent['source_pins'].items():
        assert byte_pin(old['current-source/'+name])==value
        if name=='README.md':historical_readme_document(ROOT,data,old['current-source/'+name],value)
