    assert ALLOWED_PATHS==frozenset({'.gitattributes','src/main/java/org/jlinalg/cli/JLinAlgCli.java','tools/literature/render_review.py','tools/literature/reviewed-uses.json','tools/literature/repeat_catalog.py','tools/literature/check_review_ui.cjs','tools/literature/check_repeat_review_ui.cjs'})
    snapshots=['papers.json','tool-inventory.json','summary.json','catalog.md','implementation-plan.md','README.md','WARNINGS.md','biomart-source-coverage.json','biomart-render-shared-source-compatibility.json','biomart-root-readme-evolution.json']
    for name in snapshots:assert files['catalog-snapshot/'+name]==(data/name).read_bytes()
    for name in ['literature-review.html','literature-warnings.html']:assert files['site-snapshot/'+name]==(ROOT/'site'/name).read_bytes()
    assert files['catalog-snapshot/reviewed-uses.json']==old['catalog-snapshot/reviewed-uses.json']==(ROOT/'tools/literature/reviewed-uses.json').read_bytes();assert files['catalog-snapshot/papers.json']==old['catalog-snapshot/papers.json'];papers=json.loads((data/'papers.json').read_bytes());verify_fixed_cohort(ROOT,data,papers);reviews=json.loads((ROOT/'tools/literature/reviewed-uses.json').read_bytes())['reviews'];verify_review_extension(ROOT,data,reviews);assert len(papers)==250 and len(reviews)==952 and sum(len(p['tools']) for p in papers)==2450 and sum(len(r.get('supporting_evidence',[])) for r in reviews)==328
    before={t['id']:t for t in json.loads(old['catalog-snapshot/tool-inventory.json'])};current={t['id']:t for t in json.loads((data/'tool-inventory.json').read_bytes())};assert len(before)==len(current)==390 and {n for n in before if before[n]!=current[n]}=={'biomart'} and before['biomart']['implementation_status']=='missing';metadata=biomart_metadata(ROOT,data);assert all(current['biomart'][k]==v for k,v in metadata.items()) and current['biomart']['paper_count']==7;counts=json.loads((data/'summary.json').read_bytes())['implementation_status_counts'];assert (counts['native-subset-validated'],counts['upstream-adapter-validated'],counts['missing'])==(17,65,249);registry=load_catalog_registry(ROOT);assert len(registry)==len({r['id'] for r in registry})==428 and {t['tool_id'] for paper in papers for t in paper['tools']}<={r['id'] for r in registry}
    coverage=json.loads((data/'biomart-source-coverage.json').read_bytes());assert coverage['new_reviews_added']==0 and coverage['reviewed_uses_preserved']==952 and [r['paper_id'] for r in coverage['roles']]==['P049','P117','P134','P162','P223','P238','P250'];get=lambda name:json.loads(files['build/literature-review/biomart-runtime/'+name]);audit=get('catalog-render-1/primary-audit/primary-source-audit.json');assert (audit['source_XML_hashes_verified'],audit['fulltext_DOIs_verified'],audit['observations_verified'],audit['reviewed_uses_verified'],audit['supporting_pointers_verified'])==(250,250,2450,952,328) and audit==json.loads(old['catalog-snapshot/loftee-source-audit.json']);assert get('catalog-render-1/primary-audit/COMPLETED.json')['frozen_audit_bytes_preserved']
    gates=get('catalog-scientific-gates-2/COMPLETED.json');assert gates['status']=='passed-biomaRt-and-all-nine-unchanged-inherited-scientific-gates' and len(gates['checks'])==p['scientific_gates']==10 and not gates['frozen_scientific_sources_or_verifiers_changed'];assert all(pin(ROOT/n)==v for n,v in gates['source_pins'].items());ui=get('catalog-ui-2/COMPLETED.json');assert ui['page']==pin(ROOT/'site/literature-review.html') and ui['warning_page']==pin(ROOT/'site/literature-warnings.html') and not ui['remote_mutations'];general=get('catalog-ui-2/general/ui-validation.json');focused=get('catalog-ui-2/biomart/biomart-ui-verification.json');assert general['status']==focused['status']=='passed' and len(general['checks'])==p['general_browser_checks']==299 and len(focused['checks'])==p['focused_browser_checks']==5 and focused['document_width']<=390 and not focused['page_errors'];assert all(pin(ROOT/n)==v for n,v in [*ui['source_pins'].items(),*ui['input_pins'].items()]);assert 'ignore_patterns("literature-review.html", "literature-warnings.html")' in (ROOT/'.github/workflows/pages.yml').read_text(encoding='utf8');lines=(data/'SHA256SUMS').read_text(encoding='utf8').splitlines();manifest={r.split('  ',1)[1]:r.split('  ',1)[0] for r in lines};assert len(manifest)==len(lines) and set(manifest)=={f.name for f in data.iterdir() if f.is_file() and f.name!='SHA256SUMS'} and all(pin(data/n)['sha256']==v for n,v in manifest.items()) and b'\r\n' not in (data/'SHA256SUMS').read_bytes();assert pin(ROOT/'build/cli/omicsmatic-0.3.7.jar')==p['canonical_executable_unchanged'];print('Verified250 papers/2450 observations/952 unchanged reviews;82 new scoped integrations/85 including existing;249 missing;10 scientific gates and304 browser checks. Whole goal remains active.');return p

